// Find replies to my own posts via the notifications timeline, and draft
// replies for them. Reply text is generated by the voice layer (T2); the
// only static string here is a minimal, voice-neutral degradation fallback
// that is logged as DEGRADED (I5-b) - never a cozy canned phrase.
import { appendLog } from './log.mjs';
import { generateReply } from './voice.mjs';

const ACCOUNT_SELECTOR = '[data-testid="SideNav_AccountSwitcher_Button"]';

// Read the signed-in handle from the live session so nothing is baked in.
// Falls back to opts.handle, then to '' (no filtering) when it cannot be read.
async function readMyHandle(page) {
  const text = await page.locator(ACCOUNT_SELECTOR).first().innerText({ timeout: 5000 }).catch(() => '');
  const ats = [...text.matchAll(/@(\w+)/g)];
  return ats.length ? ats[ats.length - 1][1] : '';
}

// Minimal, generic, voice-neutral utterance used only when the LLM path is
// unavailable. Not a template bank: one neutral line, always marked.
const FALLBACK = '收到，晚点回复。';

async function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

export async function scanReplies(page, opts = {}) {
  const maxAgeHours = opts.maxAgeHours ?? 48;
  const cutoff = Date.now() - maxAgeHours * 3600_000;
  const myHandle = (opts.handle || '').replace(/^@/, '') || (await readMyHandle(page));

  await page.goto('https://x.com/notifications', { waitUntil: 'domcontentloaded', timeout: 45000 });
  await sleep(6000);

  const found = [];
  const arts = await page.locator('article[data-testid="tweet"]').all();
  for (const art of arts) {
    const nameBox = await art.locator('[data-testid="User-Name"]').first().innerText().catch(() => '');
    const handleLine = (nameBox.split('\n').find((l) => l.trim().startsWith('@')) || '').trim();
    const author = handleLine.replace('@', '');
    if (!author || (myHandle && author === myHandle)) continue;

    const body = await art.innerText().catch(() => '');
    // Same two signals as before, but against the live handle: the
    // "Replying to @me" header, or @me on the first line of the tweet.
    const replyingToMe = myHandle
      ? (new RegExp('Replying to[\\s\\S]{0,40}@' + myHandle + '(?![\\w])', 'i').test(body)
        || new RegExp('@' + myHandle + '(?![\\w])', 'i').test(body.split('\n')[0] || ''))
      : /Replying to[\s\S]{0,40}@\w+/.test(body);
    if (!replyingToMe) continue;

    const href = await art.locator('a[href*="/status/"]').first().getAttribute('href').catch(() => null);
    if (!href) continue;
    const idMatch = href.match(/status\/(\d+)/);
    if (!idMatch) continue;

    const when = await art.locator('time').first().getAttribute('datetime').catch(() => null);
    if (when && new Date(when).getTime() < cutoff) continue;

    found.push({ tweetId: idMatch[1], author, url: 'https://x.com' + href, text: extractText(body), when });
  }
  return dedupe(found);
}

function extractText(body) {
  const lines = body.split('\n').map((l) => l.trim()).filter(Boolean);
  const skip = /^(Follow|Replying to|@|·|\d|Show|Translated|Verified|See)/;
  const texts = lines.filter((l) => !skip.test(l) && !l.startsWith('@') && l.length > 1);
  const best = texts.slice(-2).join(' ').trim();
  return best.slice(0, 200);
}

function dedupe(list) {
  const seen = new Set();
  return list.filter((x) => (seen.has(x.tweetId) ? false : (seen.add(x.tweetId), true)));
}

// ---- A5: interact in OTHER people's comment sections --------------------
// Targets come ONLY from the x-home / x-following timeline pools (R1): the
// shared normalizer already ran in perceive/timeline, and this function
// re-checks the whitelist + likes floor + language so a dirty row can never
// become a reply target. Own posts are excluded (R1). Pure so it is directly
// assertable.
export function selectOthersReplyCandidates(list, opts = {}) {
  const minLikes = opts.minLikes ?? 10;
  const myHandle = String(opts.myHandle || '').replace(/^@/, '').toLowerCase();
  // Lane routing (T2): growth-intent targets are preferred when the lane
  // rule is enabled (default true). The pool is never emptied: content
  // targets still return when no growth row survives the filter. The stable
  // partition keeps the existing within-group order intact (R1-1/R1-3).
  const prefersGrowth = (opts.laneRules && opts.laneRules.replyPrefersGrowth) !== false;
  const out = [];
  for (const raw of list || []) {
    const c = raw && typeof raw === 'object' ? raw : {};
    const source = c.source || '';
    if (source !== 'x-home' && source !== 'x-following') continue;
    const author = String(c.author || '').replace(/^@/, '').toLowerCase();
    if (myHandle && author === myHandle) continue;
    if (c.likes != null && Number(c.likes) < minLikes) continue;
    if (!['zh', 'en'].includes(String(c.lang || '').toLowerCase())) continue;
    if (!c.url || !c.text) continue;
    out.push(c);
  }
  if (prefersGrowth && out.some((c) => c.intent === 'growth')) {
    return [...out.filter((c) => c.intent === 'growth'), ...out.filter((c) => c.intent !== 'growth')];
  }
  return out;
}

// R2: the item handed to the generation layer carries the FULL tweet text
// (never slice(0,80)), the author handle and the like count together. The
// 200-char cap in extractText() above is for the notifications scan and is
// untouched; timeline text is used verbatim.
export function draftOthersReplyFor(item) {
  const t = (item && item.text) || '';
  if (!t || !item.author || item.likes == null) {
    appendLog('replies: othersReply item missing text/author/likes; skipping');
    return null;
  }
  return draftReplyFor(item);
}
// Async by contract (T2-b): reply text always comes from the voice layer,
// driven by the other person's text. Falls back to a neutral utterance only
// when voice returns nothing, and every fallback is logged as DEGRADED.
export async function draftReplyFor(item) {
  try {
    const text = await generateReply(item);
    if (text) return text;
  } catch (e) {
    appendLog(`replies: DEGRADED draftReplyFor failed (${e.message}); using neutral fallback`);
    return FALLBACK;
  }
  appendLog('replies: DEGRADED draftReplyFor voice returned nothing; using neutral fallback');
  return FALLBACK;
}
